import React, { useState } from "react";
import axios from "axios";
import "../styles/Signup.css";

const SignupPage = () => {
  const [formData, setFormData] = useState({
    name: "",
    phone: "",
    email: "",
    password: "",
    userType: "",
  });
  const [error, setError] = useState("");
  const [isLogin, setIsLogin] = useState(false); // Track if user is on Login form

  // Handle input change
  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setFormData({ ...formData, [name]: value });
  };

  // Handle form submission (Signup)
  const handleSignup = async (e) => {
    e.preventDefault();
    setError(""); // Reset the error message before submitting

    // Validate form fields
    if (!formData.name || !formData.phone || !formData.email || !formData.password || !formData.userType) {
      setError("All fields are required!");
      return;
    }

    try {
      const response = await axios.post("http://localhost:5001/api/auth/signup", formData);
      alert(response.data.message);
      setFormData({
        name: "",
        phone: "",
        email: "",
        password: "",
        userType: "",
      });
    } catch (err) {
      setError(err.response?.data?.message || "Something went wrong! Please try again.");
    }
  };

  // Handle form submission (Login)
  const handleLogin = async (e) => {
    e.preventDefault();
    setError(""); // Reset the error message before submitting

    // Validate form fields
    if (!formData.phone || !formData.password) {
      setError("Phone number and password are required!");
      return;
    }

    try {
      const response = await axios.post("http://localhost:5001/api/auth/login", formData);
      alert(response.data.message);
      // You can store the token and redirect to another page here
    } catch (err) {
      setError(err.response?.data?.message || "Invalid phone number or password");
    }
  };

  return (
    <div className="auth-container">
      <div className="auth-card">
        <h2>{isLogin ? "Login" : "Sign Up"}</h2>
        <form className="auth-form" onSubmit={isLogin ? handleLogin : handleSignup}>
          {!isLogin && (
            <>
              <input
                type="text"
                name="name"
                placeholder="Full Name"
                value={formData.name}
                onChange={handleInputChange}
                required
              />
              <input
                type="text"
                name="phone"
                placeholder="Phone Number"
                value={formData.phone}
                onChange={handleInputChange}
                required
              />
              <input
                type="email"
                name="email"
                placeholder="Email Address"
                value={formData.email}
                onChange={handleInputChange}
                required
              />
              <input
                type="password"
                name="password"
                placeholder="Password"
                value={formData.password}
                onChange={handleInputChange}
                required
              />
              <select
                name="userType"
                value={formData.userType}
                onChange={handleInputChange}
                required
              >
                <option value="" disabled>Select User Type</option>
                <option value="owner">Owner</option>
                <option value="manager">Manager</option>
                <option value="lorry_manager">Lorry Manager</option>
              </select>
            </>
          )}

          {isLogin && (
            <>
              <input
                type="text"
                name="phone"
                placeholder="Phone Number"
                value={formData.phone}
                onChange={handleInputChange}
                required
              />
              <input
                type="password"
                name="password"
                placeholder="Password"
                value={formData.password}
                onChange={handleInputChange}
                required
              />
            </>
          )}

          {/* Error message display */}
          {error && <p className="error-message">{error}</p>}

          {/* Submit button */}
          <button type="submit" className="btn btn-primary">
            {isLogin ? "Login" : "Sign Up"}
          </button>
        </form>

        {/* Toggle between Login and Signup */}
        <p>
          {isLogin ? "Don't have an account?" : "Already have an account?"}
          <span className="toggle-link" onClick={() => setIsLogin(!isLogin)}>
            {isLogin ? "Sign up here" : "Login here"}
          </span>
        </p>
      </div>
    </div>
  );
};

export default SignupPage;
